--{{{充值部分迁移
function SDKHelper:SendPurchase(temp)
    if not NetManager:Get():GetGameServerIsConnect() and self:CheckGameState(ClientDataManager:Get():GetGameState()) then
        print("设置GameState---->", ClientDataManager:Get():GetGameState())
        ClientDataManager:Get():SetGameState(GameState.Reconnecting)
    end
    print("GameState", ClientDataManager:Get():GetGameState())
    cs_coroutine.start(function()
        while not NetManager:Get():GetGameServerIsConnect() or not self:CheckGameState(ClientDataManager:Get():GetGameState()) do
            print("延时发送", ClientDataManager:Get():GetGameState())
            coroutine.yield(CS.UnityEngine.WaitForSeconds(0.5))
        end
        print("发送充值", ClientDataManager:Get():GetGameState())
        if temp then
            if SDKHelper:Get():ChickGoogleSdk() then
                ActivitySubsystem:Get():SendMsg_Purchase_Google_Shipment(temp.goodsId, temp.orderId, temp.orderNo, temp.purchaseToken, temp.markCode, temp.passRid)
                GoogleSDKRechargeLog:Get():SendLog()
                GoogleSDKRechargeLog:Get():AddLog("1BeginGoogleChick", temp.logInfo)
            else
                ActivitySubsystem:Get():SendMsg_Purchase_Quick_Shipment(temp.goodsId, temp.orderId)
                self:SendPurchaseLog("SendPurchase", temp.orderId, temp.orderNo, temp.goodsId, temp.purchaseToken)
            end
            self.ChargeOrderTab[temp.orderId] = temp
        else
            self:SimpleSendNext()
        end

    end)
end
function SDKHelper:SendNext()
    if self.Queue and self.Queue:GetSize() > 0 then
        self.ChargeOrderTab[self.CurValue.orderId] = nil
        self.CurValue = self.Queue:DeQueueBack()
        self.IsPay = true
        self:SendPurchase(self.CurValue)
        self:SendPurchaseLog("SendNext", self.CurValue.orderId, self.CurValue.orderNo, self.CurValue.goodsId, self.CurValue.purchaseToken)
    else
        self.IsPay = false
        self.Count = 0
        self.CurValue = nil
    end
end
function SDKHelper:SimpleSendNext()
    self.Count = 0
    self:SendNext()
    self:SendPurchaseLog("SimpleSendNext","","","","")
end
function SDKHelper:ReSend()
    if self.Count and self.Count < 20 then
        cs_coroutine.start(function()
            self.Count = self.Count + 1
            local waitForSeconds = self.Count
            if self.CurValue then
                self.Queue:EnQueueFront(self.CurValue)
                if self.Count < 5 then
                    waitForSeconds = self.Count
                elseif self.Count < 10 then
                    waitForSeconds = self.Count * 10
                else
                    waitForSeconds = self.Count * 100
                end
                coroutine.yield(CS.UnityEngine.WaitForSeconds(waitForSeconds))
                self:SendPurchaseLog("ReSend","触发再次充值","","","")
                self:SendNext()
            end
        end)
    else
        self:SimpleSendNext()
    end
end

function SDKHelper:AddPurchase(orderId, orderNo, goodsId, purchaseToken, packageName, logInfo, markCode, passRid)
    if self.ChargeOrderTab[orderId] == nil then
        local temp = {}
        temp.goodsId = goodsId
        temp.orderId = orderId
        temp.orderNo = orderNo
        temp.purchaseToken = purchaseToken
        temp.logInfo = logInfo
        temp.markCode = markCode
        temp.passRid = passRid
        self.Queue:EnQueueFront(temp)
    end
    print("IsPay", ClientDataManager:Get():GetGameState(), self.IsPay)
    if not self.IsPay then
        self.IsPay = true
        self.CurValue = self.Queue:DeQueueBack()
        self.Count = 0
        self:SendPurchase(self.CurValue)
    end
    self:SendPurchaseLog("AddPurchase", orderId, orderNo, goodsId, purchaseToken)
end
---  充值Log
function SDKHelper:SendPurchaseLog(_logInfo1, _logInfo2, _logInfo3, _logInfo4, _logInfo5)
    local _logInfo = string.format("RechargeLogInfo:%s----%s----%s----%s----%s", _logInfo1, _logInfo2, _logInfo3, _logInfo4, _logInfo5)
    print(  _logInfo)
    if _logInfo ~= "" then
        local data = QuickTaData:GetChongZhiLog(
                PlayerDataManager:Get():GetPlayerRID(),
                CS.ServerTime:Get():ConvertDateTimeInt(CS.ServerTime:Get():ServerTimeNow()),
                _logInfo
        )
        QuickTa:Get():TrackEvent(TrackEventNames.ChongZhiLog, data)
    end
end
function SDKHelper:CheckGameState(state)
    return state == GameState.Login_GameServer or state == GameState.CrossDay
end
